/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Curve, Ellipse, Line2D, Mul, Parabola, ParametricRegion, Point2D, Point3D, Polygon, Pow, Rational, Segment2D, Segment3D, Sym, Triangle, fn, mul, parametricRegionList, pi, pow, symbols } from '../../src';
import { at, sympyMatches, sympyStr } from '../sympy-str';

describe("doctests of sympy.vector.parametricregion", () => {
  it("ParametricRegion((t, t**2), (t, -1, 2))", () => {
    const t = new Sym('t');
    expect(sympyStr(ParametricRegion([t, pow(t, Rational.of(2n, 1n, { gcd: 1n }))], [t, -1, 2]))).toBe('ParametricRegion((t, t**2), (t, -1, 2))');
  });
  it("ParametricRegion((x, y), (x, 3, 4), (y, 5, 6))", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(ParametricRegion([x, y], [x, 3, 4], [y, 5, 6]))).toBe('ParametricRegion((x, y), (x, 3, 4), (y, 5, 6))');
  });
  it("ParametricRegion((r*cos(theta), r*sin(theta)), (r, -2, 2), (theta, 0, pi))", () => {
    const [r, theta] = symbols('r theta');
    expect(sympyStr(ParametricRegion([mul(r, fn('cos', [theta], { evaluate: false })), mul(r, fn('sin', [theta], { evaluate: false }))], [r, -2, 2], [theta, 0, pi]))).toBe('ParametricRegion((r*cos(theta), r*sin(theta)), (r, -2, 2), (theta, 0, pi))');
  });
  it("ParametricRegion((a*cos(t), b*sin(t)), t)", () => {
    const [a, t, b] = symbols('a t b');
    expect(sympyStr(ParametricRegion([mul(a, fn('cos', [t], { evaluate: false })), mul(b, fn('sin', [t], { evaluate: false }))], t))).toBe('ParametricRegion((a*cos(t), b*sin(t)), t)');
  });
  it("circle.parameters", () => {
    const [r, theta] = symbols('r theta');
    expect(sympyMatches([r, theta], '(r, theta)')).toBe(true);
  });
  it("circle.definition", () => {
    const [r, theta] = symbols('r theta');
    expect(sympyMatches([mul(r, fn('cos', [theta], { evaluate: false })), mul(r, fn('sin', [theta], { evaluate: false }))], '(r*cos(theta), r*sin(theta))')).toBe(true);
  });
  // a function that did not come from the library
  //   circle.limits
  //   => {theta: (0, pi)}
  it.todo("circle.limits");
  it("circle.dimensions", () => {
    const [r, theta] = symbols('r theta');
    expect(sympyStr(ParametricRegion([mul(r, fn('cos', [theta], { evaluate: false })), mul(r, fn('sin', [theta], { evaluate: false }))], r, [theta, Rational.of(0n, 1n, { gcd: 1n }), pi]).dimensions)).toBe('1');
  });
  it("parametric_region_list(p)", () => {
    expect(sympyStr([at(parametricRegionList(Point2D(Rational.of(2n, 1n, { gcd: 1n }), Rational.of(5n, 1n, { gcd: 1n }), { evaluate: false })), 0)])).toBe('[ParametricRegion((2, 5))]');
  });
  it("parametric_region_list(c)", () => {
    const t = new Sym('t');
    expect(sympyStr([at(parametricRegionList(Curve([pow(t, Rational.of(3n, 1n, { gcd: 1n })), mul(Rational.of(4n, 1n, { gcd: 1n }), t)], [t, Rational.of(-3n, 1n, { gcd: 1n }), Rational.of(4n, 1n, { gcd: 1n })])), 0)])).toBe('[ParametricRegion((t**3, 4*t), (t, -3, 4))]');
  });
  it("parametric_region_list(e)", () => {
    expect(sympyStr([at(parametricRegionList(Ellipse(Point2D(Rational.of(1n, 1n, { gcd: 1n }), Rational.of(3n, 1n, { gcd: 1n }), { evaluate: false }), Rational.of(2n, 1n, { gcd: 1n }), Rational.of(3n, 1n, { gcd: 1n }))), 0)])).toBe('[ParametricRegion((2*cos(t) + 1, 3*sin(t) + 3), (t, 0, 2*pi))]');
  });
  it("parametric_region_list(s)", () => {
    expect(sympyStr([at(parametricRegionList(Segment2D(Point2D(Rational.of(1n, 1n, { gcd: 1n }), Rational.of(3n, 1n, { gcd: 1n }), { evaluate: false }), Point2D(Rational.of(2n, 1n, { gcd: 1n }), Rational.of(6n, 1n, { gcd: 1n }), { evaluate: false }))), 0)])).toBe('[ParametricRegion((t + 1, 3*t + 3), (t, 0, 1))]');
  });
  it("parametric_region_list(poly)", () => {
    const v1 = parametricRegionList(Polygon(Point2D(Rational.of(0n, 1n, { gcd: 1n }), Rational.of(1n, 1n, { gcd: 1n }), { evaluate: false }), Point2D(Rational.of(2n, 1n, { gcd: 1n }), Rational.of(-3n, 1n, { gcd: 1n }), { evaluate: false }), Point2D(Rational.of(5n, 1n, { gcd: 1n }), Rational.of(3n, 1n, { gcd: 1n }), { evaluate: false }), Point2D(Rational.of(-2n, 1n, { gcd: 1n }), Rational.of(3n, 1n, { gcd: 1n }), { evaluate: false })));
    expect(sympyStr([at(v1, 0), at(v1, 1), at(v1, 2), at(v1, 3)])).toBe('[ParametricRegion((2*t, 1 - 4*t), (t, 0, 1)), ParametricRegion((3*t + 2, 6*t - 3), (t, 0, 1)), ParametricRegion((5 - 7*t, 3), (t, 0, 1)), ParametricRegion((2*t - 2, 3 - 2*t), (t, 0, 1))]');
  });
});

